@Entity @Table(name="culture_sources") public class CultureSource{@Id private UUID id;@Column(name="content_id",nullable=false)private UUID contentId;@Enumerated(EnumType.STRING)@Column(name="source_type",nullable=false)private SourceType sourceType;private String citation;@Column(name="source_person_name")private String sourcePersonName;private String relation;@Enumerated(EnumType.STRING)@Column(name="consent_status",nullable=false)private ConsentStatus consentStatus;@Column(name="recording_date")private LocalDate recordingDate;private String locality;@Column(name="contributor_id")private String contributorId;@Column(name="created_at",nullable=false)private Instant createdAt;protected CultureSource(){}}
